previewCss:
.darma-loader-darma-b15-skater-spin { --accent: var(--loader-color, #9333ea); --accent-2: var(--loader-secondary-color, #f0abfc); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b15-skater-spin .darma-loader-darma-b15-skater-spin__rig { position: absolute; inset: 0; animation: darma-loader-darma-b15-skater-spin-skate-turn calc(var(--loader-speed, 1s) * .85) linear infinite; }
.darma-loader-darma-b15-skater-spin .darma-loader-darma-b15-skater-spin__torso { position: absolute; left: 45%; top: 12%; width: 10%; height: 62%; border-radius: 6px; background: linear-gradient(var(--accent-2), var(--accent)); }
.darma-loader-darma-b15-skater-spin .darma-loader-darma-b15-skater-spin__arms { position: absolute; left: 16%; top: 28%; width: 68%; height: 7%; border-radius: 4px; background: var(--accent-2); transform-origin: 50% 50%; animation: darma-loader-darma-b15-skater-spin-skate-pull calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
.darma-loader-darma-b15-skater-spin .darma-loader-darma-b15-skater-spin__blade { position: absolute; left: 40%; top: 74%; width: 20%; height: 5%; border-radius: 3px; background: #e2e8f0; }
.darma-loader-darma-b15-skater-spin .darma-loader-darma-b15-skater-spin__ice { position: absolute; left: 26%; right: 26%; bottom: 16%; height: 6%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 55%, transparent); animation: darma-loader-darma-b15-skater-spin-skate-ice calc(var(--loader-speed, 1s) * .85) ease-in-out infinite; }
@keyframes darma-loader-darma-b15-skater-spin-skate-turn { 0%, 100% { transform: scaleX(1); } 25% { transform: scaleX(.08); } 50% { transform: scaleX(-1); } 75% { transform: scaleX(.08); } }
@keyframes darma-loader-darma-b15-skater-spin-skate-pull { 0%, 100% { transform: scaleX(1); } 45%, 60% { transform: scaleX(.34); } }
@keyframes darma-loader-darma-b15-skater-spin-skate-ice { 0%, 100% { transform: scaleX(1); opacity: .6; } 50% { transform: scaleX(1.25); opacity: .9; } }

